// Move constructors and destructors should be noexcept
class MyClass {
public:
    MyClass(MyClass&& other) noexcept { /* ... */ }
    ~MyClass() noexcept = default;
};

try {
    try {
        // inner code
        throw std::runtime_error("inner error");
    } catch (...) {
        // Add context and rethrow
        std::throw_with_nested(
            std::runtime_error("outer context")
        );
    }
} catch (const std::exception& e) {
    // Will print both outer and inner messages
    std::cerr << e.what() << '\n';
    try {
        std::rethrow_if_nested(e);
    } catch (const std::exception& nested) {
        std::cerr << "  caused by: " << nested.what() << '\n';
    }
}

class MyClass {
public:
    // Function try block for constructor (catches base/ member init errors)
    MyClass(int x) try
        : member_(initialize(x))
    {
        // constructor body
    } catch (const std::exception& e) {
        std::cerr << "Construction failed: " << e.what();
        throw;  // Must rethrow — object didn't fully construct
    }
private:
    SomeType member_;
};

// exception
// +-- bad_alloc            (new fails)
// +-- bad_cast             (dynamic_cast fails)
// +-- bad_typeid           (typeid on null pointer)
// +-- logic_error          (precondition violations)
// |   +-- invalid_argument (bad argument value)
// |   +-- domain_error
// |   +-- length_error     (too long, e.g., string::resize)
// |   +-- out_of_range     (at() with invalid index)
// +-- runtime_error        (runtime errors)
//     +-- range_error
//     +-- overflow_error
//     +-- underflow_error

try {
    std::vector<int> v(5);
    v.at(10) = 0;  // throws std::out_of_range
} catch (const std::out_of_range& e) {
    std::cerr << "Index out of bounds: " << e.what();
}
